{
  "spec": "functional_routing_objective_v2",
  "created": "2026-11-04",
  "status": "TUNED-20261104-AUTO",
  "status_note": "Weights chosen autonomously per Ben's 2026-11-04 directive item 7 (normalize, bounded sensitivity checks, documented choice; no pause for approval). Every term and weight is re-read by fr_objective at every solve; this file is the only place weights live. Rationale per term in weight_sensitivity log + README. Any weight here can be replaced by Ben at any time; the re-solve is checkpoint-based. | 2026-11-04 signed-deficit correction applied after the figure review caught opposite-sign robot curves. | 2026-11-04 evening: attachment_deviation + actuator_length terms added (Ben directive), signed deficit in force.",
  "read_at": "solve time (fresh jsondecode in fr_objective)",
  "terms": [
    {
      "name": "torque_capacity_deficit",
      "class": "primary_capacity",
      "weight": 100.0,
      "normalization": "sum_tau_target_abs (sum over the pose grid of |tau_target|)",
      "definition": "sum over pose grid of max(0, |tau_target| - proj), where proj = tau_primary * sign(tau_target): the SIGNED meet-or-beat deficit. A wrong-sign torque projects negative and costs |tau_target| + |tau_robot| - strictly more than producing nothing (Ben 2026-11-04: opposite sign from the human target will not do).",
      "sign_convention": "same-axis signed convention; wrong-sign torque is penalized, never credited toward the meet"
    },
    {
      "name": "usable_rom_shortfall",
      "class": "primary_rom",
      "weight": 40.0,
      "normalization": "grid size (fraction of poses, so the term lives in [0,1])",
      "definition": "fraction of pose-grid cells where |tau_primary| < |tau_target| (usable motion range primary, master item 8); report-only companion: fraction of cells feasible"
    },
    {
      "name": "torque_shape",
      "class": "shape",
      "weight": 0.5,
      "normalization": "mean over grid of (tau_primary - tau_target)^2 / mean(tau_target.^2)",
      "definition": "small, explicitly weighted torque-shape penalty (master item 8): squared residual to the SIGNED target curve. Defined SEPARATELY from the capacity terms; its small weight guarantees it cannot remove the deficit incentive. Never an off-axis torque term.",
      "sensitivity": "\u00b12x perturbation leaves the chosen designs unchanged within solver noise (weight_sensitivity log)"
    },
    {
      "name": "bpa_bpa_overlap_soft",
      "class": "soft_penalty",
      "weight": 2.0,
      "normalization": "sleeve inflated diameter at rest per pose (depth reported in mm as well)",
      "definition": "soft BPA-BPA interference (handoff item 9 / master item 8): summed overlap depth between the group's OWN parallel BPA sleeves from the pose-dependent inflated envelopes, physically simultaneous poses only. Depth and extent reported per pose."
    },
    {
      "name": "retained_bpa_corridor_soft",
      "class": "soft_penalty",
      "weight": 2.0,
      "normalization": "sleeve inflated diameter at rest per pose (extent reported in mm as well)",
      "definition": "v2 (Ben 2026-11-04): soft interference against RETAINED INNER-LAYER BPA sleeve corridors (fr_envelope kind 'bpa_sleeve'/'bpa_end'), evaluated at physically simultaneous poses. Depth/extent recorded every evaluation. An outer-layer BPA is never INFEASIBLE for crossing an inner layer's sleeve corridor - it pays this penalty; rigid fittings and tackle blocks of inner layers stay HARD (retained_rigid_envelopes).",
      "added_by": "Ben's 2026-11-04 directive item 6"
    },
    {
      "name": "attachment_deviation",
      "class": "regularizer",
      "weight": 2.0,
      "normalization": "mean displacement in mm divided by 25 mm",
      "definition": "Ben 2026-11-04 (Connor-methods lineage, light): mean displacement of the movable attachments from their ORIGINAL human seed points, owning-body frame. Keeps the force vector roughly aligned with the anatomy it replaces and prevents the far-off-bone solutions accepted by old Opt_run/Opt_run_Ext campaigns. Shortening is never penalized by this term."
    },
    {
      "name": "actuator_length",
      "class": "regularizer",
      "weight": 2.0,
      "normalization": "lengthening beyond seed length, fraction of seed (L0Seed+tendonSeed)",
      "definition": "Ben 2026-11-04: only LENGTHENING penalized \u2014 shortening is free. Per-group weights make long muscles pay more: grac 8, vas_int 4, bifemlh 4 (lengthWeightOverrides), default 2. Makes the long pinned+bowden setup more expensive for gracilis than a small reverse pulley.",
      "lengthWeightOverrides": [
        {
          "name": "grac",
          "weight": 8.0
        },
        {
          "name": "vas_int",
          "weight": 4.0
        },
        {
          "name": "bifemlh",
          "weight": 4.0
        }
      ]
    }
  ],
  "forbidden": [
    "off_axis_torque_penalty in ANY form, including inherited regularizers disguised as another term (master item 8; handoff item 9). Secondary joint torques are RECORDED in the evaluation report and never penalized.",
    "any hard universal muscle-to-muscle clearance constraint (BPA-BPA overlap is soft; only rigid hardware/bone and the z=0 centerline are hard)",
    "enforcing inner-layer BPA SLEEVE corridors as a HARD clearance constraint (Ben 2026-11-04: that was the stage-1 layering demo's unintended hard BPA-BPA constraint; rigid fittings/tackle of inner layers remain hard)"
  ],
  "hard_constraints": [
    {
      "name": "centerline_z0",
      "definition": "sideSign * z_pelvis >= 0 for EVERY candidate attachment point and mechanical mount anchor, transformed into the pelvis frame at EVERY evaluated pose (handoff item 8, verbatim). sideSign = +1 (right side of record). Sign flips / absolute values forbidden. Tolerance 1e-4 m, stated per evaluation in rep.cinfo.",
      "tol": 0.0001
    },
    {
      "name": "foot_occupancy_ban",
      "definition": "No BPA body, end fitting, or tackle block may occupy the foot (talus_r, calcn_r, toes_r). Tendons may route through and terminate on the foot. Enforced by owning-body membership of sleeve/fitting/tackle anchors plus the fitting-tip position rule on the tibia. Tolerance 1e-4 m, stated per evaluation.",
      "tol": 0.0001
    },
    {
      "name": "required_tendon_spans",
      "definition": "minFootTendonSpan_m and minKneeTendonSpan_m computed by fr_spans from the route geometry + hardware clearance over the full motion range (contract placeholders resolved by the implementer, master item 6). Tendon length must cover the maximum required span. Normalized by the procured hardware length; tolerance 1e-6, stated per evaluation.",
      "tol": 1e-06
    },
    {
      "name": "transmission_feasibility",
      "definition": "no PulleyInfeasible or PulleySlack cell on the required grid; strain within [strain floor, KMAX]; gain <= tackle line parts; at most ONE tackle (BiPam_pulley2 documented limit); discrete config consistent (nBPA, series sections, physical sheave count, reeving kept distinct). Cell-fraction normalizations; tolerances 1e-12, stated per evaluation.",
      "tol": 1e-12
    },
    {
      "name": "rated_hardware_loads",
      "definition": "tackle-block vector reaction R and any 180-deg reversing sheave radial load 2T must not exceed the assigned family's catalog capacity (S 400 N / M 667 N / L 3003 N). Catalog capacities are weight capacities whose dynamic interpretation is UNRESOLVED (handoff Open items); the assembly WLL is not assumed. Under-rated configurations are flagged in the report, never silently resized. Normalized by capacity; tolerance 1e-6, stated per evaluation.",
      "tol": 1e-06
    },
    {
      "name": "bone_exclusion",
      "definition": "route clearance to the owning bones (clouds today; packaging_v2 SDF model with quantified registration error when it lands) >= inflated radius + rigid clearance. Tolerance 1e-4 m, stated per evaluation.",
      "tol": 0.0001
    },
    {
      "name": "retained_rigid_envelopes",
      "definition": "v2: rigid fittings and tackle blocks of already-placed deeper layers (fr_envelope kind 'rigid_*') as hard obstacles at physically simultaneous poses. BPA sleeve corridors of inner layers are the SOFT term retained_bpa_corridor_soft instead (Ben 2026-11-04). Tolerance 1e-4 m, stated per evaluation.",
      "tol": 0.0001
    }
  ],
  "lengthWeightOverrides": [
    {
      "name": "grac",
      "weight": 8.0
    },
    {
      "name": "vas_int",
      "weight": 4.0
    },
    {
      "name": "bifemlh",
      "weight": 4.0
    }
  ]
}
